    } on Object {
      _syncEnd();
      rethrow;
    }
    if (nextGrid.length > _maxRows) _maxRows = nextGrid.length;
    _lastGrid = nextGrid;
    _lastContent = view.content;
    _cursorState.apply(_output, view.cursor, forceHome: wroteCells);
    _logSink?.writeln('--- cell frame ---\n${view.content}');
  }

