  void clearScreen() {
    _output.write('\x1b[H\x1b[2J');
    _lastGrid = null;
    _lastContent = null;
    _cursorState.invalidate();
  }

  @override
  void insertAbove(String line) {
    if (!_modes.altScreenEnabled) {
      _output.writeln(line);
      _cursorState.invalidate();
