//
// The view is built LAZILY: dropped frames never pay for `model.view()`
// — the old eager call site assembled the whole screen string upstream
// only to throw it away.
Future<void> render(View Function() buildView, {bool force = false}) async {
  final nowMicros = frameClock.elapsedMicroseconds;
  if (lastRenderMicros >= 0 && minFrameMicros > 0 && !force) {
    final delta = nowMicros - lastRenderMicros;
    if (delta < minFrameMicros) {
      debugFramesDropped++;
      tracer?.event({'t': nowMicros, 'ev': 'drop'});
      if (!redrawArmed) {
        redrawArmed = true;
        Timer(Duration(microseconds: minFrameMicros - delta), () {
          redrawArmed = false;
          if (_running) enqueue(const RenderTickMsg());
        });
      }
      return;
    }
  }
  final buildStart = frameClock.elapsedMicroseconds;
  final v = buildView();
  final buildUs = frameClock.elapsedMicroseconds - buildStart;
  final renderStart = frameClock.elapsedMicroseconds;
  _renderer?.render(v);
  final renderUs = frameClock.elapsedMicroseconds - renderStart;
  debugFramesPainted++;
  lastRenderedView = v;
  lastRenderMicros = frameClock.elapsedMicroseconds;
  tracer?.event({
    't': frameClock.elapsedMicroseconds,
    'ev': 'paint',
    'build_us': buildUs,
    'render_us': renderUs,
  });
}

// gh-1197 AC3: a throwing view()/renderer must never kill painting —
// the run continues underneath and a dead pipeline looks exactly like
// the silent freeze (no bytes for minutes, then the teardown burst).
// The guard logs loudly (same convention as the update()/runCmd()
// guards), invalidates the renderer so the NEXT frame is one full
// repaint from clean state (a mid-frame throw can strand partial
// diff state, e.g. an unclosed BSU), and schedules the repaint. The
// exception is rethrown only when NOTHING has ever painted — a
// program that cannot paint its initial screen has nothing to heal
// into, so it dies loudly instead of freezing on a blank glass.
var renderedOnce = false;
var lastRenderFailed = false;
Future<void> renderGuarded({bool force = false}) async {
  try {
    await render(_runningModel!.view, force: force);
    renderedOnce = true;
    lastRenderFailed = false;
  } catch (e, st) {
    if (!renderedOnce) rethrow;
    final repeatFailure = lastRenderFailed;
    lastRenderFailed = true;
    _renderer?.invalidate();
    lastRenderMicros = -1;
    redrawArmed = false;
    stderr
      ..writeln('Caught render exception (frame pipeline self-heals): $e')
      ..writeln(st);
    tracer?.event({
      't': frameClock.elapsedMicroseconds,
      'ev': 'render_error',
      'err': '$e',
    });
    // A repeat retry lands only on the next REAL message: re-arming
    // immediately would hot-spin a permanently throwing view through
    // catch -> RenderTick -> catch forever.
    if (_running && !repeatFailure) enqueue(const RenderTickMsg());
  }
}

void scheduleResizeMsg() {
  final width =
      _width ?? (stdout.hasTerminal ? stdout.terminalColumns : 80);
  final height =
      _height ?? (stdout.hasTerminal ? stdout.terminalLines : 24);
  enqueue(WindowSizeMsg(width, height));
}

// Process one message: update model / fire side-effects.
// Returns true when the view may have changed and a re-render is needed.
// Does NOT call render() — the event loop renders once per drained batch.
Future<bool> applyMsg(Msg rawMsg) async {
  var msg = rawMsg;
  final model = _runningModel!;
  if (_filter != null) {
    final filtered = _filter!(model, msg);
    if (filtered == null) return false;
    msg = filtered;
