Future<void> restoreTerminal() async {
  if (!_running) return;
  if (_disableRenderer) return;
  _setRawMode(true);
  final m = _runningModel;
  if (m != null) {
    if (_unicodeCoreSupported) _renderer?.setUnicodeCore(true);
    _renderer?.restore(m.view());
  }
}

void println([Object? value]) => send(PrintLineMsg('${value ?? ''}'));
void printf(String template, [List<Object?> args = const []]) =>
    send(PrintLineMsg(_formatProgram(template, args)));

Future<void> wait() async {
  await _finished?.future;
}

Future<(Object?, Model)> _runCore(Model initial) async {
  if (_running) {
    throw StateError('Program is already running');
  }
  _running = true;
  _killed = false;
  _finished = Completer<void>();
  _activityWake = null;
  _runningModel = initial;
  _logClose = null;

  // Opt-in startup phase timer: set DART_TUI_BENCH=1 to enable.
  final benchEnabled = Platform.environment['DART_TUI_BENCH'] == '1';
  final benchSw = benchEnabled ? (Stopwatch()..start()) : null;
  void bench(String label) {
    if (benchSw == null) return;
    stderr.writeln('[bench] +${benchSw.elapsedMilliseconds}ms\t$label');
  }

  bench('start');

  final queue = Queue<Msg>();

  void enqueue(Msg msg) {
    queue.add(msg);
    _activityWake?.complete();
    _activityWake = null;
  }

  // [send] pushes to [_msgs]; bridge it into the same queue as stdin/ticks.
  // Without this listener, async side-effects (e.g. HTTP progress/completion)
  // never reach [applyMsg].
  final StreamSubscription<Msg> externalMsgSub = _msgs.stream.listen(
    (Msg msg) {
      if (_running) {
        enqueue(msg);
      }
    },
  );

  Future<void> waitForActivity() async {
    while (_running && queue.isEmpty) {
      _activityWake = Completer<void>();
      await _activityWake!.future;
    }
  }

  Future<void> runCmd(Cmd? cmd) async {
    if (cmd == null || !_running) return;
    try {
      final msg = await Future<Msg?>.value(cmd());
      if (msg != null) enqueue(msg);
    } catch (e, st) {
      if (!_disableCatchPanics) {
        stderr.writeln('Caught command exception: $e');
        stderr.writeln(st);
      }
      enqueue(InterruptMsg());
    }
  }

  final minFrameMicros = _fps > 0 ? (1000000 / _fps).round() : 0;
  final frameClock = Stopwatch()..start();
  var lastRenderMicros = -1;
  var redrawArmed = false;
  View? lastRenderedView;
  // Keypress→paint trace sink: injected via [withTracer] or the
  // FA_TUI_TRACE env file path. Zero cost when neither is set.
  final tracer = _tracer ??= switch (Platform.environment['FA_TUI_TRACE']) {
    final String path? => FileFrameTracer(File(path)),
    _ => null,
  };
  // Frame throttle WITHOUT blocking the event loop. The old inline
  // Future.delayed stalled message pickup behind every early frame (a key
  // press arriving mid-frame waited out the remaining budget): with the
  // spinner ticking at 10 Hz and output flushing at 20 Hz, keystrokes
  // routinely queued behind ~16 ms sleeps and every interaction felt
  // rubber-banded. Instead an early frame is DROPPED and one timer defers
  // a RenderTickMsg; the loop keeps draining messages meanwhile and paints
  // the LATEST view when the tick lands. Renders still happen strictly in
  // this awaited sequence, so frames can never paint out of order or race.
  //

The guard matches the existing `runCmd` guard conventions. The `enqueue` inside the catch adds to `queue` directly and wakes the activity loop. But note — the catch runs inside the event loop between batches. `enqueue` adds to queue and completes `_activityWake`. But if this happens while the loop is in `waitForActivity`, waking works. If it happens during batch drain, queue non-empty → next iteration picks it up. But wait: the render happens at the END of the loop body, after batch drain:

```dart
if (needsRender && _running) {
  await renderGuarded(force: inputDriven);
}
if (_running) {
  await waitForActivity();
}
```

The enqueued RenderTickMsg is in the queue before waitForActivity → the loop continues (while _running) → drains the tick → applyMsg returns true → renderGuarded heals. 

One more check — `lastRenderedView` is set in render() after successful paint. On failure it's not updated. Is `lastRenderedView` used anywhere for re-render? grep.

