    if (call != null) {
      toolUse = true;
      final block = ToolCall(
        id: call['id'] as String,
        name: call['name'] as String,
        arguments: (call['arguments'] as Map<String, dynamic>? ?? const {})
            .cast<String, dynamic>(),
