      events
        ..add((
          ToolCallStartEvent(contentIndex: contentIndex, partial: partial()),
          0,
        ))
        ..add((
          ToolCallEndEvent(
            contentIndex: contentIndex,
            toolCall: block,
            partial: partial(
              content: List.of(blocks),
              reason: StopReason.toolUse,
