  events.add((
    DoneEvent(
      reason: toolUse ? StopReason.toolUse : StopReason.stop,
      message: partial(
        content: blocks,
        reason: toolUse ? StopReason.toolUse : StopReason.stop,
      ),
    ),
    0,
  ));
