      _lastContent = null;
      _cursorState.invalidate();
    }
    _terminalViewState.apply(_output, view, altScreen: wantsAlt);
    if (view.windowTitle != _lastTitle) {
      if (view.windowTitle.isNotEmpty) {
        _output.write(windowTitleSequence(view.windowTitle));
      }
