+          wroteCells = true;
+        } else {
+          wroteCells = _diffAndEmit(nextGrid);
+          _syncEnd();
+        }
       }
+    } on Object {
+      _syncEnd();
+      rethrow;
     }
     if (nextGrid.length > _maxRows) _maxRows = nextGrid.length;
     _lastGrid = nextGrid;

