// ── Grid building ──────────────────────────────────────────────────────────

/// Parse [content] into a 2-D grid of [_Cell]s.
/// Rows are separated by '\n'. Within each row, we walk grapheme clusters
/// while tracking the active SGR and OSC 8 state.
List<List<_Cell>> _buildGrid(String content) {
