        wroteCells = nextGrid.isNotEmpty;
        wroteCells = _diffAndEmit(nextGrid) || wroteCells;
        _syncEnd();
      } else {
        final shift = _detectScrollShift(prev, nextGrid);
        if (shift != null) {
