  void scroll(int n, {bool up = true}) {
    if (n <= 0) return;
    // ESC[nS = scroll up n lines; ESC[nT = scroll down n lines
    _output.write(up ? '\x1b[${n}S' : '\x1b[${n}T');
    _lastLines = const <String>[];
    _lastContent = '';
    _hasRenderedFrame = false;
    _cursorState.invalidate();
  }

  @override
  void invalidate() {
    _lastLines = const <String>[];
    _lastContent = '';
    _hasRenderedFrame = false;
    _cursorState.invalidate();
  }
