  final IOSink _output;
  final IOSink? _logSink;
  final TerminalModeState _modes;
  bool _unicodeCoreEnabled = false;
  bool _syncUpdates = false;
  bool _syncOpen = false;

  List<List<_Cell>>? _lastGrid;
  String? _lastContent;
  String _lastTitle = '';
