        if (_running) {
          enqueue(InterruptMsg());
        }
      }));
    }

    while (_running) {
      // Drain all pending messages without rendering between them.
      // This ensures rapid key events are processed immediately without
      // each one incurring the FPS-throttle delay.
      var needsRender = false;
      var inputDriven = false;
      if (queue.isNotEmpty) {
        tracer?.event({
          't': frameClock.elapsedMicroseconds,
          'ev': 'batch',
          'n': queue.length,
        });
      }
      while (queue.isNotEmpty && _running) {
        final msg = queue.removeFirst();
        if (msg is KeyMsg || msg is MouseMsg) inputDriven = true;
        needsRender |= await applyMsg(msg);
        final m = _runningModel;
        if (m is OutcomeModel && m.outcome != null) {
          _running = false;
          break;
        }
      }
      // Render once for the entire drained batch. Input-driven batches
      // force the paint: echo latency IS the perceived typing speed, and
      // a key landing inside the fps window must not wait out the
      // throttle (kitty's input_delay/repaint_delay split). A forced
      // paint also carries any collapsed output frame with it.
      if (needsRender && _running) {
        await renderGuarded(force: inputDriven);
      }
      if (_running) {
        await waitForActivity();
      }
    }
  } finally {
    await externalMsgSub.cancel();
    // Await stdin subscription cancellation explicitly so stdin is fully
    // released before _shutdown() marks the program done. Without this,
    // the Dart event loop keeps running after main() returns (waiting for
    // the unawaited cancel future), leaving the terminal hanging until Ctrl-C.
    final inputSub = _inputSub;
    _inputSub = null;
    await inputSub?.cancel();
    tracer?.event({'t': frameClock.elapsedMicroseconds, 'ev': 'quit'});
    final activeTracer = _tracer;
    _tracer = null;
    await activeTracer?.close();
    _shutdown();
    await _logClose;
    if (!_disableRenderer) {
      // Move to a fresh line so the shell prompt appears cleanly after exit,
      // then flush so all ANSI reset sequences (show cursor, exit alt-screen)
      // actually reach the terminal before the shell gets control.
      _output.writeln();
      await _output.flush();
    }
  }

  return (_killed ? StateError('program killed') : null, _runningModel!);
}

void _shutdown() {
  if (!_running && (_finished?.isCompleted ?? true)) return;
  _running = false;
  final activityWake = _activityWake;
  _activityWake = null;
  if (activityWake != null && !activityWake.isCompleted) {
    activityWake.complete();
  }

